        int n = nums[i];
        int[] newNums = new int[nums.length - 1];
        for (int j = 0; j < nums.length; j++) {
            if (j != i) {
                newNums[j] = nums[j];
            }
        }
        List<List<Integer>> permutations = permute(newNums);
        for (List<Integer> permutation : permutations) {
            permutation.add(n);
            result.add(permutation);
        }
    }
    return result;
}

