import java.util.List;

public int findLargestSubstring(List<String> strings) {
	int largestSubstring = 0;
	for (int i = 0; i < strings.size(); i++) {
		String str = strings.get(i);
		int invSize = str.length();
		for (int j = 0; j < str.length(); j++) {
			if (str.charAt(j) == ' ') {
				invSize--;
			}
		}
		for (int k = 0; k < str.length(); k++) {
			String invStr = new StringBuilder(str).reverse().toString();
			if (strings.contains(invStr)) {
				largestSubstring = Math.max(largestSubstring, invSize);
			}
		}
	}
	return largestSubstring;
}

public int findLargestSubstring(List<String> strings) {
    // Create a map to store the lengths of each string
    Map<String, Integer> stringLengths = new HashMap<>();
    for (String string : strings) {
        stringLengths.put(string, string.length());
    }

    // Sort the map by length in descending order
    Map<String, Integer> sortedLengths = stringLengths.entrySet()
            .stream()
            .sorted(Collections.reverseOrder(Map.Entry.comparingByValue()))
            .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue));

    // Initialize the largest substring and its length
    String largestSubstring = "";
    int largestLength = 0;

    // Iterate through the sorted map and find the largest substring
    for (Map.Entry<String, Integer> entry : sortedLengths.entrySet()) {
        String key = entry.getKey();
        int index = strings.indexOf(key);
        if (index == -1) {
            continue;
        }

        String substring = strings.get(index).substring(0, entry.getValue());
        if (substring.length() > largestLength) {
            largestSubstring = substring;
            largestLength = substring.length();
        }
    }

    // Return the length of the largest substring
    return largestLength;
}

