public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize a boolean array to keep track of visited n-tersections
    boolean[] visited = new boolean[n];

    // Initialize a queue for the breadth-first search
    Queue<Integer> queue = new LinkedList<>();

    // Mark the starting n-tersection as visited and add it to the queue
    visited[start] = true;
    queue.offer(start);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the next n-tersection to visit
        int current = queue.poll();

        // If the current n-tersection is the ending n-tersection, return "can be travelled"
        if (current == end) {
            return "can be travelled";
        }

        // Loop through all n-tersections that are connected to the current n-tersection
        for (int next : paths[current]) {
            // If the next n-tersection has not been visited, mark it as visited and add it to the queue
            if (!visited[next]) {
                visited[next] = true;
                queue.offer(next);
            }
        }
    }

    // If the queue is empty and the ending n-tersection has not been visited, return "cannot be travelled"
    return "cannot be travelled";
