        // Initialize a boolean array to keep track of visited n-tersections
        boolean[] visited = new boolean[n];

        // Initialize a queue to perform BFS
        Queue<Integer> queue = new LinkedList<>();

        // Mark the starting n-tersection as visited and add it to the queue
        visited[start[0]] = true;
        queue.add(start[0]);

        // Loop until the queue is empty
        while (!queue.isEmpty()) {
            // Get the next n-tersection from the queue
            int current = queue.remove();

            // If the current n-tersection is the ending n-tersection, return "can be travelled"
            if (current == end[0]) {
                return "can be travelled";
            }

            // Loop through all the adjacent n-tersections
            for (int i = 0; i < paths.length; i++) {
                // If the adjacent n-tersection is not visited and is not blocked, mark it as visited and add it to the queue
                if (paths[current][i] == 1 && !visited[i]) {
                    visited[i] = true;
                    queue.add(i);
                }
            }
        }

        // If the queue is empty and the ending n-tersection was not visited, return "cannot be travelled"
        return "cannot be travelled";
    }
