        if (distance[node1] == -1) {
            return -1;
        }

        int distance = 0;
        for (int i = 0; i < node1; i++) {
            if (edges[node1][i] == 1) {
                distance++;
            }
        }

        for (int i = 0; i < node2; i++) {
            if (edges[node2][i] == 1) {
                distance++;
            }
        }

        return distance;
