public String sortString(String s) {
  // Initialize a map to count the characters in the string.
  Map<Character, Integer> charCounts = new TreeMap<>();
  for (char c : s.toCharArray()) {
    Integer count = charCounts.get(c);
    if (count == null) {
      count = 0;
    }
    charCounts.put(c, count++);
  }

  // Define a helper function to sort the character array.
  Comparator<Character> comp = new Comparator<Character>() {
    @Override
    public int compare(Character o1, Character o2) {
      if (charCounts.get(o1) > charCounts.get(o2)) {
        return 1;
      } else if (charCounts.get(o1).equals(charCounts.get(o2))) {
        return o1.compareTo(o2);
      } else {
        return -1;
      }
    }
  };

  // Sort the character array using the comparator defined above.
  Character[] characters = new Character[charCounts.size()];
  int index = 0;
  for (Character c : charCounts.keySet()) {
    characters[index++] = c;
  }
  Arrays.sort(characters, comp);

  StringBuilder sortedString = new StringBuilder();
  for (int i = 0; i < characters.length; i += 2) {
    sortedString.append(characters[i]);
  }
  return sortedString.toString();
}
