public boolean hasAllCodes(String s, int k) {
    int n = s.length();
    if (n < k) {
        return false;
    }
    for (int i = 0; i <= n - k; i++) {
        String substr = s.substring(i, k);
        if (!isValid(substr, k)) {
            return false;
        }
    }
    return true;
}

private boolean isValid(String substr, int k) {
    for (int i = 0; i < k; i++) {
        if (substr.charAt(i) != '0' && substr.charAt(i) != '1') {
            return false;
        }
    }
    return true;
