private void selectionSort(String[] arr, String[] result) {
    int minIndex = 0;
    for (int i = 0; i < arr.length; i++) {
        if (arr[i].compareTo(arr[minIndex]) < 0) {
            minIndex = i;
        }
    }
    result[minIndex] = arr[minIndex];
    for (int i = minIndex + 1; i < arr.length; i++) {
        if (arr[i].compareTo(result[minIndex]) < 0) {
            minIndex = i;
            result[minIndex] = arr[minIndex];
        }
    }
}
