public int maxSumOfTwoSubarrays(int[] arr, int k) {
    int n = arr.length;
    int[] sum = new int[n];
    sum[0] = arr[0];
    for (int i = 1; i < n; i++) {
        sum[i] = sum[i - 1] + arr[i];
    }
    int max = sum[0];
    for (int i = 1; i < n; i++) {
        for (int j = 0; j < i; j++) {
            int currSum = sum[i] - sum[j] + arr[j];
            if (currSum <= k && currSum > max) {
                max = currSum;
            }
        }
    }
    return max;
}
