import java.util.Scanner;

public class MaxAbsoluteSum {

    /**
     * A method to find the maximum absolute sum of any subarray within a given integer array.
     * @param nums The input integer array.
     * @return The maximum absolute sum of any subarray.
     */
    public static int maxAbsoluteSum(int[] nums) {
        // Initialize maximum absolute sum and current sum
        int max = 0, sum = 0;

        // Iterate over the input array
        for (int i = 0; i < nums.length; i++) {

            // Update current sum
            sum += nums[i];

            // Update maximum absolute sum
            max = Math.max(max, Math.abs(sum));

            // Check if current sum exceeds maximum absolute sum
            if (sum < 0) {
                sum = 0;
            }
        }

        // Return maximum absolute sum
        return max;
    }

