public static boolean isSteppingNumber(int num) {
    // Initialize the previous digit to -1
    int prevDigit = -1;

    // Iterate through the digits of the number
    while (num > 0) {
        // Get the current digit
        int digit = num % 10;

        // Check if the current digit is not equal to the previous digit and not equal to zero
        if (digit != prevDigit && digit != 0) {
            // Decrement the digit
            digit--;

            // Check if the decremented digit is not equal to the current digit
            if (digit != num % 10) {
