public static int longestLine(int[][] mat) {
    int m = mat.length;
    int n = mat[0].length;
    int maxLength = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            int length = 0;
            boolean[][] visited = new boolean[m][n];
            dfs(mat, i, j, visited, length);
            maxLength = Math.max(maxLength, length);
        }
    }
    return maxLength;
}

private static void dfs(int[][] mat, int i, int j, boolean[][] visited, int length) {
    if (i < 0 || j < 0 || i >= mat.length || j >= mat[0].length || visited[i][j] || mat[i][j] == 0) {
        return;
    }
    visited[i][j] = true;
    length++;
    dfs(mat, i - 1, j, visited, length);
    dfs(mat, i + 1, j, visited, length);
    dfs(mat, i, j - 1, visited, length);
    dfs(mat, i, j + 1, visited, length);
    dfs(mat, i - 1, j - 1, visited, length);
    dfs(mat, i + 1, j + 1, visited, length);
}
