private static int traverse(int[][] mat, int i, int j) {
    int maxLength = 1;
    int row = i;
    int col = j;
    while (row >= 0 && col >= 0 && mat[row][col] == 1) {
        maxLength++;
        row--;
        col--;
    }
    row = i;
    col = j;
    while (row < mat.length && col < mat[row].length && mat[row][col] == 1) {
        maxLength++;
        row++;
        col++;
    }
    return maxLength;
}
