public class LongestLine {
    public static int longestLine(int[][] mat) {
        // Initialize the longest line length and its orientation.
        int longestLine = 0;
        int orientation = 0; // 0 for horizontal, 1 for vertical, 2 for diagonal, 3 for anti-diagonal

        // Iterate over each row of the matrix.
        for (int i = 0; i < mat.length; i++) {
            // Iterate over each column of the matrix.
            for (int j = 0; j < mat[0].length; j++) {
                if (mat[i][j] == 0) {
                    continue;
                }

                // Check if the current cell is the starting point of a line.
                if (i == 0 || j == 0 || mat[i - 1][j] == 0 || mat[i][j - 1] == 0) {
                    // Initialize the current line length.
                    int lineLength = 1;

                    // Iterate over the adjacent cells to the starting point.
                    for (int k = i, l = j; k < mat.length && l < mat[0].length; k++, l++) {
                        // Check if the current cell is part of the line.
                        if (mat[k][l] == 1) {
                            lineLength++;
                            continue;
                        }

                        // Check if the current line is longer than the longest line found so far.
                        if (lineLength > longestLine) {
                            longestLine = lineLength;
                            orientation = getOrientation(k - i, l - j);
                        }

                        // Start a new line if the current cell is not part of the line.
                        lineLength = 1;
                    }
                }
            }
        }

        return longestLine;
    }

    // A method to get the orientation of a line based on the difference between the starting point and the end point.
    private static int getOrientation(int diffX, int diffY) {
        if (diffX == 0) {
            return 0; // Horizontal
        } else if (diffY == 0) {
            return 1; // Vertical
        } else if (diffX == diffY) {
            return 2; // Diagonal
        } else {
            return 3; // Anti-diagonal
        }
    }

