        int start = 0;
        int end = word.length() - 1;
        while (start < end) {
            char temp = word.charAt(start);
            word.replace(start, start + 1, String.valueOf(word.charAt(end)));
            word.replace(end, end + 1, String.valueOf(temp));
            start++;
            end--;
        }
        result.append(word);
    }

    return result.toString();
}
